INSERT INTO "feed_items"("project_id","item_id","source_id","signal_id","signal_revision","kind","title","summary","body","source_kind","source_label","external_id","url","origin_status","priority","tags_json","author","disposition","read_at","revision","source_created_at","source_updated_at","imported_at","updated_at") VALUES('molis-work-v1-demo','feeditem-884e3ec4-8c33-4b3c-b589-9031f0a15021','demo-github',NULL,NULL,'github_notification','PR #418 请确认完成依据是否写进事件记录','Review 要求核对：工作何时开始、提交了什么、为什么可以算完成。','请对照 CORE 的约定：从约定、报告到收尾要形成完整记录。这条通知需要人决定是否并入当前 Goal。','github','GitHub · molis-work','demo-github-pr-418','https://github.com/example/molis-work/pull/418','inbox','medium','["GitHub","Review"]','octocat','inbox',NULL,1,'2026-09-16T06:18:00.000Z','2026-09-16T06:18:00.000Z','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
INSERT INTO "feed_items"("project_id","item_id","source_id","signal_id","signal_revision","kind","title","summary","body","source_kind","source_label","external_id","url","origin_status","priority","tags_json","author","disposition","read_at","revision","source_created_at","source_updated_at","imported_at","updated_at") VALUES('molis-work-v1-demo','feeditem-9a6c5a16-b216-468a-a762-916fb1ea44bd','demo-gmail',NULL,NULL,'gmail_message','第一次打开项目时，默认该先看目标还是先开会话？','合作方问首页落点。决定仍在 Goals 的 DECIDE，这里只保留邮件事实。','如果两个入口同时强调，新用户会停在选择上。请产品给一个默认落点，另一个入口仍可从同一工作台到达。','gmail','Gmail · 产品反馈','demo-gmail-landing',NULL,'inbox','medium','["Gmail","产品"]','Mina <partner@example.com>','inbox',NULL,1,'2026-09-16T05:42:00.000Z','2026-09-16T05:42:00.000Z','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
