INSERT INTO "feed_items"("project_id","item_id","source_id","signal_id","signal_revision","kind","title","summary","body","source_kind","source_label","external_id","url","origin_status","priority","tags_json","author","disposition","read_at","revision","source_created_at","source_updated_at","imported_at","updated_at") VALUES('molis-work-v1-demo','feeditem-c0d7522a-9676-4747-be5d-f36737aa6d95','feed-source-f34498b13c742f0d0f851765e48fe4d6',NULL,NULL,'rss_entry','第一次把模糊想法收成目标树','用户要能从列表看出下一步、阻塞和完成依据。','长程任务最容易在换对话后丢失共同进度。先把模糊想法收成目标树，再决定谁做下一步。这篇文章和当前示例项目的主 Goal 直接相关。','rss','Solidot','https://example.com/posts/goal-tree-first-run','https://www.solidot.org/','inbox','medium','["RSS","产品设计"]','Solidot','inbox',NULL,1,'2026-09-16T04:25:00.000Z','2026-09-16T04:25:00.000Z','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
